    "q": "จากประวัติ ลูกม้าคลอดตามกำหนด ขณะคลอดปกติดีทุกอย่างลูกม้าแข็งแรงสามารถลุกขึ้นมาดูดนมน้ำเหลืองได้ด้วยตัวเองภายใน 2 ชั่วโมงหลังคลอด แต่พอผ่านมา 1 วัน เจ้าของสังเกตเห็นว่าลูกม้าเริ่มแสดงอาการซึม ไม่ค่อยลุกดูดนม และมีเยื่อเมือกสีเหลือง ซึ่งแม่ม้าเคยให้ลูกแสดงอาการแบบนี้ในคลอดครั้งที่แล้วโดยลูกม้าตายหลังจากคลอดได้ 3 วัน จากลักษณะอาการดังกล่าวควรทำการตรวจทางห้องปฏิบัติการด้วยเทคนิคใด",
    "options": [
      "Glutaraldehyde coagulation test",
      "Single radial immunodiffusion (SRID)",
      "Jaundiced foal agglutination (JFA) test",
      "Peritoneal-to-serum creatinine ratio"
    ],
    "answer": 2,
    "explain": "ลูกม้าปกติดีหลังคลอดและได้กินนมน้ำเหลือง ต่อมาซึม ไม่ค่อยดูดนม เยื่อเมือกเหลือง และแม่ตัวเดิมเคยมีลูกเป็นแบบเดียวกัน ชี้ไปที่ neonatal isoerythrolysis ซึ่งแอนติบอดีในนมน้ำเหลืองทำลายเม็ดเลือดแดงของลูก การตรวจยืนยันคือ JFA test (หรือ Coombs test) ที่ทดสอบนมน้ำเหลืองหรือซีรัมของแม่กับเม็ดเลือดแดงลูก ส่วน glutaraldehyde test และ SRID วัด IgG เพื่อหา FPT และ creatinine ratio ใช้ยืนยัน uroperitoneum",
