    "explain": "Neonatal septicemia คือภาวะที่มีแบคทีเรียหรือ toxin ในกระแสเลือด เชื้อที่พบบ่อยที่สุดเป็นแกรมลบ ช่องทางหลักคือจากระบบสืบพันธุ์ของแม่ม้า และจากสิ่งแวดล้อมผ่านสายสะดือ การหายใจ การกิน และบาดแผล แมลงดูดเลือดไม่ใช่ช่องทางของ septicemia ในลูกม้าแรกคลอด ปัจจัยเสี่ยงสำคัญคือ FPT การคลอดก่อนกำหนด การคลอดยาก และ placentitis",
    "source": "สไลด์ Neonatal septicemia ที่แปะในสรุปปลายภาค Equine Med Surg รุ่นพี่ ฉบับครบ หน้า 13",
