    "explain": "Sepsis score ให้คะแนนจากประวัติ อาการ และผลแล็บ คะแนนยิ่งมากยิ่งบ่งว่าเป็น sepsis หัวข้อ IgG ให้คะแนนกลับทาง คือ IgG น้อยกว่า 200 mg/dl ได้ 4 คะแนน 200-400 ได้ 3 คะแนน 400-800 ได้ 2 คะแนน และมากกว่า 800 mg/dl ได้ 0 คะแนน ข้อความที่ว่า IgG มากกว่า 800 ได้ 4 คะแนนจึงผิด ข้อความอื่นถูกทั้งหมด คือลูกม้าอายุเกิน 12 ชั่วโมงใช้ค่า IgG จริง ลูกม้าอายุไม่ถึง 12 ชั่วโมงให้ +2 ถ้าได้ดูดนมน้ำเหลืองดีและ +4 ถ้ายังไม่ได้ดูดหรือไม่แน่ใจ คะแนน 12 ขึ้นไปทำนาย sepsis ถูกราวร้อยละ 93 และ modified score ที่ตัด arterial oxygen กับ metabolic acidosis ใช้จุดตัด 11",
