    "model_answer": "Sepsis score ให้คะแนน 3 หมวด: ประวัติ (placentitis, vulvar discharge, คลอดยาก, ขนส่งแม่นาน, แม่ป่วย, ชักนำการคลอด, ท้องเกิน 365 วัน และอายุท้องสั้นหรือคลอดก่อนกำหนด) อาการ (จุดเลือดออกหรือ scleral injection, ไข้หรืออุณหภูมิต่ำ, hypotonia ซึม หมดสติ ชัก, anterior uveitis ท้องร่วง หายใจลำบาก ข้อบวม แผลเปิด) และผลแล็บ (neutrophil, band, toxic change, fibrinogen, glucose, IgG, arterial oxygen, metabolic acidosis) แต่ละหัวข้อได้ 0 ถึง 4 คะแนนตามความรุนแรง (คะแนนเต็มของแต่ละหัวข้อไม่เท่ากัน) คะแนนต่ำสุด 0 และสูงสุด 38 เมื่อรวมคะแนนสูงสุดทุกหัวข้อ (34 ถ้าไม่ได้ตรวจ arterial oxygen และ metabolic acidosis) ลูกม้าอายุเกิน 12 ชั่วโมงใช้ค่า IgG ที่ตรวจได้ ถ้าอายุไม่ถึง 12 ชั่วโมงให้ +2 เมื่อได้ดูดนมน้ำเหลืองดี และ +4 ถ้ายังไม่ได้ดูดหรือไม่แน่ใจ การแปลผล: 12 คะแนนขึ้นไปทำนาย sepsis ถูกราวร้อยละ 93, 10 คะแนนลงมาทำนายว่าไม่ใช่ sepsis ถูกราวร้อยละ 88 และ modified score ที่ตัดสองหัวข้อสุดท้ายใช้จุดตัด 11",
