    "explain": "NI เกิดเมื่อแม่ม้ามีแอนติบอดีต่อแอนติเจนบนเม็ดเลือดแดงของลูก (มักเป็นแม่หมู่เลือด Aa หรือ Qa ลบที่ผสมกับพ่อที่เป็นบวก) แอนติบอดีนี้อยู่ในนมน้ำเหลือง ลูกจึงคลอดออกมาปกติแล้วป่วยหลังกินนมน้ำเหลือง เพราะรกม้าแบบ epitheliochorial ไม่ให้แอนติบอดีผ่าน มักเกิดในท้องหลังจากแม่ถูกกระตุ้นมาแล้ว ไม่ใช่ท้องแรก และเลือดทั้งหมด (whole blood) ของแม่มีแอนติบอดีตัวเดิมในพลาสมา จึงไม่ใช้ให้ลูก",
