    "q": "ลูกม้าเพศผู้ (colt) อายุ 4 วัน มีอาการอ่อนแรงและช็อค ช่องท้องขยาย เจ้าของสังเกตไม่พบการขับปัสสาวะของลูกม้า วินิจฉัยเบื้องต้นจากประวัติและอาการว่า กระเพาะปัสสาวะแตก (ruptured bladder) และได้ส่งตัวอย่างซีรั่มเพื่อตรวจวิเคราะห์ค่าเคมีในเลือด (serum chemistry) การเปลี่ยนแปลงของค่าเคมีในซีรั่มที่สำคัญในกรณีของกระเพาะปัสสาวะแตกในลูกม้าหลังคลอด คือ",
