    "q": "ลูกม้าเพศเมีย พันธุ์โทโรเบรด อายุ 3 วัน ถูกนำส่งโรงพยาบาลสัตว์เพื่อทำการวินิจฉัยอาการซึมและไม่ค่อยกินนม ผลการตรวจร่างกายทางคลินิกมีดังต่อไปนี้ อุณหภูมิกายปกติ อัตราหายใจเร็ว (tachypnea) หัวใจเต้นเร็วกว่าปกติเล็กน้อย (mild tachycardia) ช่องท้องส่วนล่างขยาย และมีภาวะขาดน้ำ 5% ลูกม้าพยายามเบ่งขับปัสสาวะและมีปริมาณปัสสาวะเพียงเล็กน้อย วินิจฉัยเบื้องต้นว่า มีการสะสมของน้ำปัสสาวะในช่องท้อง (uroperitoneum) จากกระเพาะปัสสาวะแตก การวินิจฉัยยืนยันภาวะ uroperitoneum ทำได้โดย (5 คะแนน)",
