    "type": "short",
    "examScope": "final",
    "q": "ให้บอกแนวทางว่าจะวินิจฉัยและรักษาอย่างไร\n\nGI surgery - colic: ม้าที่ใช้รับนักท่องเที่ยว มีอาการกระวนกระวาย หายใจลำบาก คุ้ยพื้น ฟังไม่ได้ยินเสียงลำไส้ (GI sound) และเยื่อเมือก (mucous membrane) สีแดงเข้มจนม่วง",
    "keywords": [
      "ซักประวัติและตรวจร่างกาย",
      "nasogastric intubation",
      "rectal palpation",
      "abdominal ultrasound",
      "abdominocentesis",
      "blood lactate",
      "composite colic score",
      "ส่งผ่าตัด"
    ],
    "model_answer": "วินิจฉัย: ซักประวัติ (ระดับและระยะเวลาที่ปวด การกินการถ่าย การใช้งาน ยาที่ได้รับ) ตรวจร่างกายเทียบค่าปกติ (HR 30-45 ครั้งต่อนาที, RR 12-36 ครั้งต่อนาที, อุณหภูมิ 99-101.5°F, เสียงลำไส้ และเยื่อเมือกสีชมพูชุ่ม CRT น้อยกว่า 2 วินาที) ใส่ท่อ nasogastric ดู gastric reflux ล้วงตรวจทางทวารหนัก อัลตร้าซาวด์ช่องท้องดูลำไส้เล็กขยายเกิน 5 cm เจาะน้ำช่องท้องดูสีและโปรตีน วัด blood lactate แล้วรวมเป็น composite colic score เพื่อตัดสินระหว่าง medical, surgical และ euthanasia รักษา: ระงับปวดด้วย alpha-2 agonist และ flunixin meglumine โดยระวังว่ายาบดบังอาการของ strangulating lesion ระบาย gastric reflux ทางท่อ ให้สารน้ำทางหลอดเลือดดำแก้ภาวะช็อก ม้าตัวนี้ไม่มีเสียงลำไส้และเยื่อเมือกม่วงคล้ำ เข้าข่าย surgical colic ต้องส่งผ่าตัดเปิดช่องท้อง และถ้ามีลำไส้แตกหรือระบบไหลเวียนล้มเหลวรุนแรง (HR เกิน 90, PCV เกินร้อยละ 60, cyanosis) ให้พิจารณา euthanasia",
    "explain": "หลักคือแยก medical colic ออกจาก surgical colic ให้เร็วที่สุด เพราะ colic เป็นกรณีฉุกเฉิน สัญญาณของ surgical colic ได้แก่ ปวดรุนแรงไม่ตอบสนองต่อยา ไม่มีเสียงลำไส้ มี reflux ลำไส้เล็กขยาย lactate สูง และเยื่อเมือกคล้ำ",
    "source": "Equine GI I 5th year 1-2026 หน้า 16-34; Equine GI II 5th year 1-2026 หน้า 2-10",
