    "model_answer": "ก่อนวางยา: ซักประวัติ ตรวจร่างกายและสัญญาณชีพ ประเมินน้ำหนักด้วยสูตรรอบอก ตรวจสถานะวัคซีนบาดทะยัก งดหญ้าอย่างน้อย 12 ชั่วโมงและอาหารเม็ดอย่างน้อย 24 ชั่วโมง (ลดอาหารข้นล่วงหน้า 2 สัปดาห์) โดยไม่งดน้ำ เลือกพื้นที่เงียบ เรียบ สะอาด ปลอดภัย หลีกเลี่ยงอากาศร้อนจัดหรือฝน เตรียมเบาะหรือฟางรอง เชือกและ halter ผู้ช่วยที่มีประสบการณ์ pulse oximeter สาย IV สารน้ำ และยาฉุกเฉิน (atropine, epinephrine, dobutamine, dopamine) วางยา: ให้ยาซึม alpha-2 agonist เช่น xylazine 1.1 mg/kg IV (เสริม butorphanol ได้หลังม้าซึมแล้ว) รอจนซึมเต็มที่ แล้วนำสลบด้วย ketamine 1.5-2.2 mg/kg IV (ถ้าเพิ่ม diazepam เพื่อคลายกล้ามเนื้อ ใช้สูตร diazepam 0.01-0.02 mg/kg ร่วมกับ xylazine 0.5-1 mg/kg และ ketamine 1.5-2 mg/kg แทน) คงการสลบแบบ TIVA โดยเติมยาครั้งละ 1/2 ถึง 1/3 ของขนาดแรกเมื่อเริ่มตื้น ฉีดยาชาเฉพาะที่บริเวณผ่าตัดร่วมด้วย จัดท่า lateral recumbency บนเบาะ ดึงขาหน้าด้านล่างไปข้างหน้า ขาอื่นตั้งฉากกับลำตัว ไม่พลิกตัวม้า เฝ้าระวังตำแหน่งตาและ reflex, nystagmus จาก ketamine, muscle tone, HR, MM, CRT, การหายใจ และ SpO2 ให้ NSAID ระงับปวด การฟื้น: ให้ฟื้นในที่สงบ ประคองหัวและหาง ให้ม้าลุกในครั้งเดียว อยู่ในคอกจนรู้สึกตัวเต็มที่ งดอาหารจนรู้สึกตัว แล้วให้เฉพาะหญ้าใน 12 ชั่วโมงแรก",
    "explain": "การวางยาในภาคสนามมีอุปกรณ์และการเฝ้าระวังจำกัดกว่าโรงพยาบาล จึงใช้ยาฉีด (TIVA) กับหัตถการสั้นอย่างการทำหมัน และต้องวางแผนตั้งแต่การเลือกสถานที่จนถึงการฟื้น",
