    "model_answer": "สาเหตุ: น้ำหนักตัวที่มากกดทับกล้ามเนื้อและหลอดเลือดขณะนอน ร่วมกับความดันเลือดต่ำระหว่างวางยา ทำให้กล้ามเนื้อขาดเลือด เกิด anaerobic metabolism กรด lactic สะสม และกล้ามเนื้ออักเสบ มักเป็นที่กล้ามเนื้อไหล่ (triceps) และสะโพก (gluteal) จนม้าขาเจ็บหรือลุกไม่ได้ ปัจจัยโน้มนำคือ กินอาหารข้นมาก ความเครียด ความดันต่ำระหว่างผ่าตัด การวางยานาน การใช้ inhalant โดยเฉพาะ halothane และการนอนหงาย การรับมือ: ป้องกันด้วยเบาะรองหนาพอ จัดท่าถูกต้อง (ท่าตะแคงดึงขาหน้าด้านล่างไปข้างหน้าเพื่อลดแรงกดที่ triceps และ radial nerve และไม่ยืดขาจนเกินไป) รักษา MAP ให้สูงกว่า 70 mmHg ด้วยสารน้ำและ inotrope เช่น dobutamine และลดเวลาวางยา ถ้าเกิดแล้วให้ยาระงับปวดและสารน้ำ และช่วยพยุงม้าระหว่างฟื้น",
