    "id": 209585,
    "subject": "equine-medicine",
    "topic": "equine-colic-surgery",
    "year": 5,
    "type": "short",
    "examScope": "final",
    "q": "วินิจฉัยแยกโรค (Differential diagnosis) จากข้อมูลต่อไปนี้\n\nม้าโปโล (Argentina Polo Pony) ที่มีการฝึกซ้อมและเข้าร่วมการแข่งขันอย่างสม่ำเสมอ เพศเมีย น้ำหนัก 412 กิโลกรัม. อายุ 10 ปี ช่วง 3 เดือนที่ผ่านมา มีประวัติปวดท้องและมีการตอบสนองดีต่อการรักษาทางอายุรกรรมจำนวน 3 ครั้ง\nช่วงบ่ายของเมื่อวาน ม้าแสดงอาการ คุ้ยพื้น ไม่กินอาหาร Rectal Temperature 39.8 C, HR 40 bpm, RR 32 bpm, decreased gut sound ได้รับการรักษาด้วย Fluid therapy (NSS 6 L, Acetate 4 L) Flunixin meglumine 10 ml, IV การทำ gastric lavage การกรอก liquid paraffin (2 L) และ electrolyte\nเช้าวันนี้ พบขี้ 1 กอง ที่มี liquid paraffin เคลือบ ปัสสาวะปกติ มีความอยากกินอาหาร ได้รับการรักษาต่อเนื่องด้วย Fluid therapy (NSS 4 L, D5S 2 L), Flunixin meglumine 5 ml, IV และ Omeprazole paste, PO\nบ่ายวันนี้ ม้าแสดงอาการ คุ้ยพื้น นอน Rectal Temperature 38.4 C, HR 57 bpm, RR 48 bpm, decreased gut sound และได้ยินเสียง gas ได้รับการรักษาต่อเนื่องด้วย Fluid therapy (NSS 4 L, Acetate 4 L), Flunixin meglumine 5 ml, IV\nเวลา 22.00 น. ของวันนี้ Rectal Temperature 37.7 C, HR 60 bpm, RR 26 bpm with shallow pattern, CRT 2 sec with pale mucous membrane, Normal gut sound ฝั่งซ้าย และ decreased gut sound ได้ยินเสียง gas ฝั่งขวา ท้องไม่กาง ไม่พบ content ในกระเพาะอาหาร ไม่พบ Gastric reflux จากการทำ Rectal palpation พบก้อนขี้มี liquid paraffin เคลือบ และคลำพบก้อนกลม แข็ง ขนาดใหญ่บริเวณพื้นท้องฝั่งซ้าย Blood lactate 4 mmol/L Transabdominal Ultrasonography ตามตำแหน่งที่วางหัวตรวจ Complete blood count และ blood chemistry ที่เวลา 22.00 น. และ 08.30 น. ของเช้าวันต่อมา ได้ผลดังนี้\nค่า Complete blood count และ Blood chemistry\nHematology | 10 p.m. | 8.30 a.m. next day | Reference range\nPCV (%) | 16 | 12 | 32-48\nHCT (%) | 15 | 11.2 | 30-46\nHgb (g/dl) | 5.9 | 4.3 | 10-16\nRBC (*10^6/µl) | 3.26 | 2.48 | 6-12\nMCV (fl) | 46.0 | 45.2 | 34-58\nMCH | 18.1 | 17.3 | 14-20\nMCHC (g/dl) | 39.3 | 38.4 | 31-37\nWBC (*10^3 /µl) | 8.42 | 6.02 | 6-12\nNeut (*10^3 /µl) | 7.32 | 4.76 | 3-6\nLymph (*10^3 /µl) | 0.66 | 0.8 | 1.5-5\nMono (*10^3 /µl) | 0.40 | 0.45 | 0-0.6\nEo (*10^3 /µl) | 0.01 | 0.00 | 0-0.8\nBaso (*10^3 /µl) | 0.03 | 0.01 | 0-0.3\nPlatelets (*10^3/µl) | 43 | 65 | 100-400\nPlasma protein (g/dl) | 4.0 | 5.0 | 5.2-7.9\nFibrinogen (mg/dl) | 0 | 600 | 100-400\nSerum biochemistry | 1 a.m. | 9 a.m. | Reference range\nBUN (mg/dl) | 19.9 | 21.4 | 12-26\nCreat (mg/dl) | 1.74 | 1.62 | 0.5-1.7\nAST (IU/L) | 283 | 290 | 152-294\nALP (IU/L) | 52 | 57 | 105-257\nGGT (IU/L) | 5 | 5 | 9-25\nAlb ( g/dl) | - | 2.36 | 2.6-3.7\nGlob ( g/dl) | - | 1.63 | 2.9-4.4\n\nKeywords: 1. Ovarian tumors 2. Colic 3. Hemoabdomen",
    "keywords": [
      "hemoabdomen",
      "ovarian tumor",
      "ก้อนกลมแข็งที่พื้นท้องด้านซ้าย",
      "โลหิตจาง PCV 16 เป็น 12%",
      "โปรตีนต่ำและเกล็ดเลือดต่ำ",
      "large intestine impaction",
      "abdominocentesis"
    ],
    "model_answer": "1) Hemoabdomen (เลือดออกในช่องท้อง) จากเนื้องอกรังไข่ (ovarian tumor) ที่มีเลือดออก เป็นข้อที่เป็นไปได้มากที่สุด: คลำทางทวารพบก้อนกลมแข็งขนาดใหญ่ที่พื้นท้องด้านซ้าย ร่วมกับโลหิตจางรุนแรงที่แย่ลงข้ามคืน (PCV 16 เป็น 12%, Hb 5.9 เป็น 4.3 g/dl, RBC ต่ำ) โปรตีนในพลาสมาต่ำ (4.0-5.0 g/dl) albumin และ globulin ต่ำ เกล็ดเลือดต่ำ (43-65 x10^3/µl) และ fibrinogen สูงในวันถัดมา ร่วมกับเยื่อเมือกซีด หัวใจเต้นเร็ว (HR 57-60) หายใจเร็ว และ lactate สูง (4 mmol/L) เข้ากับการเสียเลือดเข้าช่องท้อง 2) Colic จาก large intestine impaction (เช่น cecum) เพราะปวดท้องซ้ำหลายครั้งที่ตอบสนองต่อการรักษาทางยา เสียงลำไส้ลดลง และได้ยินเสียงแก๊สด้านขวา 3) เลือดออกในช่องท้องจากแหล่งอื่น ยืนยันด้วยการเจาะช่องท้อง (abdominocentesis) ที่พบของเหลวเป็นเลือด และอัลตร้าซาวด์ดูก้อนที่รังไข่กับของเหลวในช่องท้อง",
    "explain": "ประวัติปวดท้องซ้ำชวนให้นึกถึงปัญหาลำไส้ก่อน แต่ PCV และโปรตีนในพลาสมาต่ำทั้งคู่ คือเสียทั้งเซลล์และพลาสมาแบบเสียเลือด PCV ยังลดลงต่อข้ามคืน และคลำพบก้อนในช่องท้อง จึงต้องคิดถึงเลือดออกในช่องท้องจากก้อนเนื้องอกรังไข่ ซึ่ง colic จากลำไส้อย่างเดียวอธิบายไม่ได้ ระบบสืบพันธุ์เป็นแหล่งของอาการปวดท้องนอกทางเดินอาหารที่ต้องคิดถึงในม้าเพศเมีย",
    "source": "Equine GI I 5th year 1-2026 หน้า 16, 25 และ 30-31",
