    "q": "คุณได้ทำการคลำตรวจพบ digital pulse ขาด้านซ้าย แรงมากกว่าขาด้านขวา\nFlexion test\nLower limb (Negative)\nFetlock (Negative)\nCarpus (Negative)\nเมื่อทำการหนีบกีบ (Hoof tester) ม้ามีอาการเจ็บบริเวณ sole ส่วน toe อาจารย์ได้ทำการ Peripheral nerve block ได้ผลดังต่อไปนี้\nPalmar digital nerve block (negative)\nAbaxial digital nerve block (Positive)\nLow four nerve block (Positive)\nหลังจากรอ 2 ชั่วโมง ได้ทำการตรวจ Joint Block ได้ผลดังนี้\nCoffin Joint (Negative)\nNavicular bursa (Negative)\n\nจากที่คุณเลือกทำการ Xray บริเวณกีบ ได้ผลดังต่อไปนี้ (ภาพ)\nComment: Radiolucency on inner hoof wall\nจากผลการตรวจทั้งหมด ม้าตัวนี้มีปัญหาอะไร (Diagnosis) ตอบไม่เกิน 1 บรรทัด",
