    "model_answer": "Subsolar abscess (ฝีใต้พื้นกีบ) บริเวณ toe ของกีบขาหน้าซ้าย",
    "explain": "ผลทุกอย่างชี้ไปที่กีบแต่อยู่นอกข้อ digital pulse ข้างซ้ายแรงกว่าบอกว่ามีการอักเสบในกีบ flexion test ลบทุกระดับ หนีบกีบแล้วเจ็บที่ sole ด้าน toe palmar digital nerve block ไม่ช่วยเพราะไม่ครอบคลุมส่วนหน้าของกีบ แต่ abaxial block ที่อยู่สูงขึ้นและชาทั้งกีบทำให้หาย ขณะที่ coffin joint และ navicular bursa block เป็นลบ จึงไม่ใช่ปัญหาในข้อหรือ navicular แนวสีดำ (radiolucency) ตามขอบพื้นล่างของ P3 และผนังกีบด้านในคือแก๊สที่แทรกอยู่ใต้พื้นกีบ เข้ากับฝีใต้พื้นกีบซึ่งเกิดเฉียบพลันในขาข้างเดียว",
