    "examScope": "final",
    "q": "After you seen the horse gait; what would you like to do next?\nChoose what your team would like to do, there is cost for owner to pay for every choice.\n- Perform an anesthetic block (200thb per site) please name your block\n- Do a flexion test (500thb)\n- Advise the owner to sell the horse (free)\n- Utilize the hoof testers (free) - please point out where would you like to apply the pressure\n- Radiograph (500thb for film) please identify technique and location\n- Ultrasound scan (1500thb) please identify your location\n- Give up - you didn't want to be a vet anyway (free)\n\nข้อมูลเคส: ในขณะที่ออกฝึกปฏิบัติงานนอกสถานที่ ณ คอกม้ากีฬา RBSC เจ้าของม้าได้ขอให้อาจารย์และนิสิตช่วยตรวจม้าที่เพิ่งซื้อมาใหม่จากต่างประเทศ เมื่อถึงประเทศไทย ม้ามีอาการขากระเผลกในบางครั้งที่ทำการฝึกขี่ ซึ่งขณะเป็นช่วงพักการแข่งขัน เจ้าของจึงขอให้อาจารย์ และนิสิตช่วยตรวจเพื่อวางแผนการใช้งาน และรักษาก่อนเปิดฤดูการแข่งขันในอีกไม่กี่เดือนข้างหน้า\nPhysical examination: On physical exam, you see a horse standing quietly. You check all four legs. There is no obvious heat or swelling. The left eye is cloudy, but appears to be free of ulceration. There are no other abnormal physical exam findings.",
    "keywords": [
      "hoof testers first",
      "flexion test of the lower limb",
      "anesthetic block from the foot up",
      "radiograph last",
      "no ultrasound"
    ],
    "model_answer": "เลือก 4 อย่าง เรียงตามนี้: 1 Utilize the hoof testers (ฟรี) กดทั่วพื้นกีบและผ่านกบ 2 Do a flexion test (500) งอส่วนล่างของขา 3 Perform an anesthetic block (200 ต่อจุด) เริ่มที่ palmar digital nerve block แล้วไล่ขึ้น 4 Radiograph (500 ต่อฟิล์ม) ของกีบ รวมท่า tangential ของ navicular bone ไม่เลือก ultrasound (1500) เพราะการตรวจชี้ไปที่กีบ ไม่ใช่เอ็น และไม่เลือกข้อแนะนำให้ขายหรือเลิกตรวจ",
    "explain": "ลำดับที่คุ้มค่าที่สุดคือเริ่มจากการตรวจที่ไม่มีค่าใช้จ่ายและไม่รุกล้ำ hoof tester เป็นจุดเริ่มที่ดีที่สุดในการหาตำแหน่งเจ็บในกีบ ตามด้วย flexion test ของส่วนล่างของขา (coffin, pastern, fetlock) แล้วฉีดยาชาจากกีบขึ้นไป ในม้าตัวนี้ palmar digital nerve block ทำให้หายเจ็บ ภาพรังสีมาเป็นขั้นสุดท้ายเมื่อรู้ตำแหน่งแล้ว ultrasound ใช้ดูเอ็นและเนื้อเยื่ออ่อน จึงไม่จำเป็นในเคสที่เจ็บในกีบ",
    "source": "แผ่นเฉลยที่พิมพ์แจกในคาบฝึก POA (ภาพในรวมข้อสอบปลายภาค Equine Med & Surg ฉบับครบ หน้า 3) ข้อ 3-6",
    "verified": "รวมข้อสอบปลายภาค Equine Med & Surg ฉบับครบ หน้า 3 (แบบฟอร์มฝึก POA Lameness 1); ถามซ้ำใน ภาพแบบฟอร์มฝึก POA Lameness Case 1 หน้า 2 และ บันทึกคาบฝึก POA ของ Vet 84 หน้า 5",
