    "passage": "คุณได้รับการเชิญให้เข้าร่วมเป็นสัตวแพทย์ประจำการแข่งขันขี่ม้า Eventing (ข้ามภูมิประเทศ) รายการชิงแชมป์แห่งประเทศไทย\nโดยได้รับมอบหมายให้เป็นสัตวแพทย์ประจำสนาม Cross-Country (กระโดดข้ามภูมิประเทศ) มีม้าเข้าร่วมการแข่งขันทั้งหมด 20 ตัว โดยปล่อยม้าตัวแรกในเวลา 06.00น.\nคุณได้เข้าประจำจุดที่ได้รับมอบหมายที่เครื่อง Water Jump 2 เพื่อเฝ้าสังเกต และทำการช่วยเหลือหากเกิดเหตุใดใด\nการแข่งขันดำเนินไปด้วยความเรียบร้อยในครึ่งแรก ขณะที่คุณกำลังจิบกาแฟอยู่นั้น วิทยุสำหรับหน่วยสัตวแพทย์ได้ดังขึ้นว่า\n“Water Jump 2 vet” “ม้าหมายเลข 120 (เข้าแข่งเป็นตัวสุดท้าย) กำลังจะผ่านเครื่องของท่าน สงสัยว่าม้ามีเลือดไหลออกทางจมูก!!!”\nจากการสังเกตด้วยสายตาอันเฉียบคมของคุณพบว่า ม้าเหมือนมีจุดเลือดไหลเล็กน้อยทางจมูกด้านซ้าย ระดับการวิ่งความเร็วสม่ำเสมอ จังหวะก้าวขาไม่บ่งชี้ต่ออาการเจ็บขา",
