    "model_answer": "1 Exercise-induced pulmonary hemorrhage (EIPH) 2 Ethmoid hematoma 3 Guttural pouch mycosis 4 Sinusitis ทั้งสี่เป็นสาเหตุของเลือดหรือน้ำมูกปนเลือดออกทางจมูก และสามข้อหลังมักเป็นข้างเดียว",
    "explain": "เลือดออกจมูกข้างเดียวในม้าที่เพิ่งออกกำลังหนัก EIPH จึงขึ้นก่อน แต่เลือดข้างเดียวต้องนึกถึงแหล่งเลือดในทางเดินหายใจส่วนต้นด้วย ethmoid hematoma ให้เลือดกำเดาข้างเดียว ปริมาณน้อย เป็นๆ หายๆ และไม่สัมพันธ์กับการออกกำลัง guttural pouch mycosis ให้เลือดกำเดาตั้งแต่ปานกลางถึงรุนแรง ส่วน sinusitis ให้น้ำมูกส่วนใหญ่ข้างเดียวและมีเลือดกำเดาได้ เสียงลำไส้ที่ลดลงเล็กน้อยหลังแข่งไม่ใช่สาเหตุของเลือดออกจมูก จึงไม่ควรใส่ colic เป็นหนึ่งใน initial diagnosis ของปัญหานี้",
    "source": "Eq Respi หน้า 15, 25, 38, 76-77; Eq Infectious Dz and Biosecurity หน้า 73",
