    "model_answer": "ส่องกล้องทางเดินหายใจ (endoscopy) ผ่านทางจมูกตั้งแต่ทางเดินหายใจส่วนต้นลงไปถึง trachea ภายใน 30-90 นาทีหลังออกกำลังเต็มที่ เพื่อดูเลือดในทางเดินหายใจ ร่วมกับทำ bronchoalveolar lavage (BAL) ตรวจ cytology หา hemosiderophage ซึ่งย้อม Prussian blue ติดสีของเหล็ก การส่องส่วนต้นยังช่วยแยก ethmoid hematoma และแหล่งเลือดในทางเดินหายใจส่วนต้นออกด้วย",
    "explain": "EIPH วินิจฉัยจากการเห็นเลือดในทางเดินหายใจหลังออกกำลังผ่านกล้อง และ BAL cytology ซึ่งไวกว่า ในม้าแข่งพบเลือดใน tracheobronchial tree ด้วยกล้อง 45-75% แต่พบด้วย cytology ของ BAL มากกว่า 90% ภาพรังสีไซนัสใช้กับปัญหาไซนัส ไม่ได้บอกเลือดจากปอด",
