    "model_answer": "Grade 2: มีเลือดเป็นทางสั้นๆ มากกว่า 2 ทาง กินพื้นที่ไม่ถึงหนึ่งในสามของเส้นรอบวง trachea",
    "explain": "เกณฑ์ grade ของ EIPH: Grade 1 คือจุดเลือดหนึ่งจุดขึ้นไป หรือทางเลือดสั้นและแคบไม่เกิน 2 ทาง Grade 2 คือทางยาว 1 ทาง หรือทางสั้นมากกว่า 2 ทางที่กินพื้นที่ไม่ถึงหนึ่งในสามของเส้นรอบวง Grade 3 คือหลายทางแยกกันกินพื้นที่เกินหนึ่งในสามแต่ไม่มีเลือดขังที่ thoracic inlet Grade 4 คือหลายทางรวมกันคลุมเกิน 90% และมีเลือดขังที่ thoracic inlet ภาพนี้มีทางสั้นมากกว่า 2 ทางจึงเกิน Grade 1 แต่ยังอยู่ในพื้นที่ไม่ถึงหนึ่งในสาม การนับเป็นจุดเลือดแล้วตอบ Grade 1 คือการมองข้ามจำนวนทางเลือด",
    "source": "Eq Respi หน้า 78",
