    "model_answer": "1 พักม้าจากการแข่งขันและการฝึกหนัก 2 ใช้ furosemide ก่อนการออกกำลังหนัก ซึ่งลดทั้งอุบัติการณ์และความรุนแรงของ EIPH 3 ลดปัจจัยเสี่ยงที่ปรับได้ คือลดงานที่หนักและเร็วมาก และเลี่ยงการออกกำลังในอากาศเย็นต่ำกว่า 20 °C 4 ยาเสริมที่เลือกใช้ได้ เช่น procoagulant (vitamin K, aminocaproic acid) bronchodilator dietary supplement (hesperidin-citrus bioflavonoids) และยาต้านการอักเสบ",
