    "q": "คุณได้รับการติดต่อให้ไปตรวจม้าในเขตจังหวัดสุพรรณบุรี โดยเจ้าของให้ข้อมูลทางโทรศัพท์เบื้องต้นดังนี้\nม้าสายทอง เพศเมีย อายุ 10 ปี พันธุ์ไทย มีอาการไม่อยากอาหาร น้ำหนักลดในช่วง 1 เดือนที่ผ่านมา เมื่อคอกม้า ลักษณะคอกเป็นคอกใต้ถุนบ้าน เลี้ยงแบบปล่อย เจ้าของนำม้าออกมาให้คุณตรวจ\nจากการซักประวัติเพิ่มเติม ได้ข้อมูลว่า เจ้าของ ชอบม้า เลยซื้อม้ามาจากเพื่อนที่มีอาชีพเลี้ยงวัวขุน ในบริเวณใกล้เคียง เมื่อประมาณ 2 เดือน ไม่ได้ทำการตรวจโรคอะไร เพราะตอนนั้นม้าดูสุขภาพดี ในช่วงที่ผ่านมาได้ให้ ยาฆ่าพยาธิ และให้ยาลดไข้ ให้น้ำเกลือ NSS มา 3 วัน วันละ 10 ขวด เมื่อทำการตรวจสุขภาพได้ข้อมูลดังต่อไปนี้\nHeart rate 100 BPM, Pulse strong and regular Respiratory rate 52 BPM, temperature 39.6 °C, Dehydration status 7%, Capillary refill time 3 seconds, Mucous membrane appear pale pink, Multiple abrasive wound on belly and limb, ataxia and stiffing on walk, presence of petechiation and gelatinous materials on the vulvar mucosa\n\nจากที่คุณทำการเก็บเลือดส่งตรวจค่า CBC และ Serum Biochemical ได้ผลดังต่อไปนี้ (Parameter: Results | Range)\nRBC (10⁶/μl): 5.1 | 6.0–12.0\nHGB (g/dl): 9.7 | 11.0–17.0\nHCT (%): 24.6 | 35.0–55.0\nMCV (μm³): 35.7 | 34.0–58.0\nMCH (pg): 24.5 | 26.0–34.0\nMCHC (g/dl): 29.1 | 31.0–35.5\nWBC (10³/μl): 12.7 | 4.0–12.00\nMonocyte (10³/μl): 2.3 | 0.1–0.8\nLymphocyte (10³/μl): 5.1 | 1.5–5.5\nGranulocyte (10³/μl): 5.3 | 2.0–8.0\nPlatelet (10³/μl): 191 | 150–400\nTotal bilirubin (mg/dl): 2.9 | 0–3.5\nAlanine transaminase (μ/l): 15 | 5–50\nγ-glutamyl transferase (μ/l): 21 | 0–87\nCreatine kinase (μ/l): 108 | 10–350\nTotal protein (g/dl): 6.0 | 5.6–7.9\nAlbumin (g/dl): 2.2 | 1.9–3.2\nGlobulin (g/dl): 3.8 | 2.4–4.7\nCalcium (mg/dl): 4.3 | 10.4–12.9\nGlucose (μ/l): 41 | 64–150\nPhosphorus (mg/dl): 1.5 | 1.8–5.6\nBlood Parasite (direct smear) negative\nจากผลที่ได้ จงระบุ Differential diagnosis มา 4 ข้อ เรียงลำดับความน่าจะเป็นไปได้มากที่สุดไปน้อยที่สุด",
    "keywords": [
      "equine infectious anemia (EIA)",
      "hypocalcemia",
      "trypanosomiasis (T. evansi)",
      "equine piroplasmosis",
      "hypochromic anemia",
      "monocytosis",
      "hypoglycemia",
      "hypophosphatemia"
    ],
    "model_answer": "1 Equine infectious anemia (EIA) 2 Hypocalcemia 3 Trypanosomiasis (Trypanosoma evansi, surra) 4 Equine piroplasmosis (Babesia caballi, Theileria equi) ผลเลือดที่ใช้: anemia (RBC, HGB, HCT ต่ำ) ร่วมกับ MCH และ MCHC ต่ำ (hypochromic) โดย MCV ยังอยู่ในช่วงปกติ leukocytosis เล็กน้อยร่วมกับ monocytosis hypocalcemia hypoglycemia และ hypophosphatemia ส่วน platelet และ total protein ปกติ และ direct smear ไม่พบ blood parasite",
    "explain": "ม้าผอมลง มีไข้ ซีด มีจุดเลือดออกที่เยื่อเมือก vulva เดินเซ และเพิ่งซื้อมาจากคนเลี้ยงวัวขุนโดยไม่ได้ตรวจโรค ภาพนี้เข้ากับโรคที่มีแมลงดูดเลือดหรือเห็บเป็นพาหะ EIA ให้ไข้ น้ำหนักลด ซีด จุดเลือดออก และ ataxia จึงอยู่อันดับแรก trypanosomiasis ติดผ่าน Tabanus ทำให้ซีด บวม น้ำหนักลด มีไข้ และขาหลังอ่อนแรงได้ piroplasmosis ติดผ่านเห็บ ทำให้มีไข้และซีด และระยะ subacute มีน้ำหนักลดร่วม แคลเซียมที่ต่ำมาก (4.3 จากช่วง 10.4-12.9 mg/dl) เป็นปัญหาทางเมแทบอลิซึมที่ต้องอยู่ใน list ด้วย direct smear ที่เป็นลบยังตัดพยาธิในเลือดไม่ได้ ต้องตรวจต่อตามโรค เช่น Woo's test และ buffy coat สำหรับ Trypanosoma, PCR และ AGID สำหรับ EIA",
    "source": "Eq Infectious Dz and Biosecurity หน้า 22-24, 60-65; Equine Parasites หน้า 64-68",
