    "q": "What joint would you like to flex?\n- Lower limb\n- The carpus\n- Upper limb\n\nข้อมูลเคส: ในขณะที่ออกฝึกปฏิบัติงานนอกสถานที่ ณ คอกม้ากีฬา RBSC เจ้าของม้าได้ขอให้อาจารย์และนิสิตช่วยตรวจม้าที่เพิ่งซื้อมาใหม่จากต่างประเทศ เมื่อถึงประเทศไทย ม้ามีอาการขากระเผลกในบางครั้งที่ทำการฝึกขี่ ซึ่งขณะเป็นช่วงพักการแข่งขัน เจ้าของจึงขอให้อาจารย์ และนิสิตช่วยตรวจเพื่อวางแผนการใช้งาน และรักษาก่อนเปิดฤดูการแข่งขันในอีกไม่กี่เดือนข้างหน้า\nPhysical examination: On physical exam, you see a horse standing quietly. You check all four legs. There is no obvious heat or swelling. The left eye is cloudy, but appears to be free of ulceration. There are no other abnormal physical exam findings.",
