    "year": 5,
    "type": "short",
    "examScope": "final",
    "q": "You've seen the horse. You've done the diagnostics. You've evaluated the problem. Now, make the diagnosis.\n- an abscess\n- navicular disease\n- ruptured suspensory ligament\n- fractured sesamoid\n- fractured distal phalanx\n- fractured proximal phalanx\n- degenerative joint disease\n- laminitis\n\nข้อมูลเคส: ในขณะที่ออกฝึกปฏิบัติงานนอกสถานที่ ณ คอกม้ากีฬา RBSC เจ้าของม้าได้ขอให้อาจารย์และนิสิตช่วยตรวจม้าที่เพิ่งซื้อมาใหม่จากต่างประเทศ เมื่อถึงประเทศไทย ม้ามีอาการขากระเผลกในบางครั้งที่ทำการฝึกขี่ ซึ่งขณะเป็นช่วงพักการแข่งขัน เจ้าของจึงขอให้อาจารย์ และนิสิตช่วยตรวจเพื่อวางแผนการใช้งาน และรักษาก่อนเปิดฤดูการแข่งขันในอีกไม่กี่เดือนข้างหน้า\nPhysical examination: On physical exam, you see a horse standing quietly. You check all four legs. There is no obvious heat or swelling. The left eye is cloudy, but appears to be free of ulceration. There are no other abnormal physical exam findings.\nผลที่ได้ระหว่างทาง: เจ้าของบอกว่าม้าใส่เกือกที่มีแผ่นเหล็กพาดด้านหลังเกือก; hoof tester เจ็บที่ส้นกีบทั้งสองข้าง ไม่เจ็บที่พื้นกีบด้านหน้า; flexion test ของ lower limb เป็นบวก ส่วน carpus และ upper limb เป็นลบ; palmar digital nerve block และ coffin joint block เป็นบวก; ถ่ายภาพรังสีกีบรวมท่า tangential (skyline)",
