    "q": "จากข้อมูลที่มี Initial problem list ของคุณมีอะไรบ้าง จงระบุมาจำนวน 3 ข้อ\n\nข้อมูลเคส: คุณได้รับการเชิญให้เข้าร่วมเป็นสัตวแพทย์ประจำการแข่งขันขี่ม้า Eventing (ข้ามภูมิประเทศ) รายการชิงแชมป์แห่งประเทศไทย โดยได้รับมอบหมายให้เป็นสัตวแพทย์ประจำสนาม Cross-Country (กระโดดข้ามภูมิประเทศ) มีม้าทั้งหมด 20 ตัว เข้าร่วมการแข่งขัน โดยปล่อยม้าตัวแรกในเวลา 06.00น. คุณได้เข้าประจำจุดที่ได้รับมอบหมายที่เครื่อง Water Jump 2 การแข่งขันดำเนินไปด้วยความเรียบร้อยในครึ่งแรก ขณะที่คุณกำลังจิบกาแฟอยู่นั้น วิทยุสำหรับหน่วยสัตวแพทย์ได้ดังขึ้นว่า “Water Jump 2 vet” “ม้าหมายเลข 120 (เข้าแข่งเป็นตัวสุดท้าย) กำลังจะผ่านเครื่องของท่าน สงสัยว่าม้ามีเลือดไหลออกทางจมูก!!!” จากการสังเกตของคุณพบว่า ม้าเหมือนมีจุดเลือดไหลเล็กน้อยทางจมูกด้านซ้าย ระดับการวิ่งความเร็วสม่ำเสมอ จังหวะก้าวขาไม่บ่งชี้ต่ออาการเจ็บขา\nจากการดำเนินการของคุณ ที่ส่งต่อให้กรรมการ ณ จุดควบคุมการแข่งขัน กรรมการตัดสินว่าให้ม้าตัวนี้ออกจากการแข่งขันทันที โดยให้คุณเป็นผู้ควบคุมนำม้าไปส่งที่โรงพยาบาลม้าภายในสนามแข่งขัน\nจากการตรวจร่างกาย ได้ข้อมูลดังต่อไปนี้\nHeart rate 75 bpm, Respiratory rate 20 time per minutes, Gutsound minor decrease, No swelling on legs, Left unilateral bloody nasal discharge",
    "keywords": [
      "left unilateral bloody nasal discharge",
      "tachycardia (HR 75 bpm)",
      "decreased gut sounds",
      "problem list = abnormal findings"
    ],
    "model_answer": "1 Left unilateral bloody nasal discharge (เลือดกำเดาข้างซ้าย) 2 Tachycardia (HR 75 bpm สูงกว่าค่าปกติ 28-44 bpm) 3 Gut sound ลดลงเล็กน้อย",
    "explain": "Problem list คือรายการความผิดปกติจากประวัติและการตรวจร่างกาย ยังไม่ใช่การวินิจฉัย จึงเขียนเป็นสิ่งที่พบ ไม่ใช่ชื่อโรค initial diagnosis เป็นขั้นถัดไปหลังจากมี problem list แล้ว",
    "source": "Equine general practice 5th year 1-2026 หน้า 45, 51",
