    "q": "Equine POA Case 3 Q1\nA 3 months old warm blood colt is presented for evaluation of intermittent fever and diarrhea for 1 week duration.\nThe foal lives on a large breeding farm in Korat with many expensive horses. The herd health program (vaccination and deworming) is excellent. No other foals have been sick other than occasional mild upper respiratory infection.\nThis foal was born normally, had excellent passive transfer, and has not been ill previously.\nOn presentation the foal was slightly depressed otherwise is in good condition and suckling from the mare. RR is 50 BPM, T is 102.5, and HR is 72 BPM. The perineum and tail are stained with diarrhea. On auscultation there is increase lung sounds on expiration and some mucoid noises can be heard in the trachea. WHAT IS YOUR PROBLEM LIST?",
