    "examScope": "final",
    "q": "ม้าเป็นสัตว์กระเพาะเดียว ทำไมต้องให้อาหารหยาบ\nแนวทางการให้อาหารม้า",
    "keywords": [
      "hindgut fermenter",
      "fibre fermented to VFA",
      "chewing and saliva",
      "stable hindgut pH and microbes",
      "forage at least 1% BW (1.5-2%)",
      "concentrate only to fill the gap",
      "change feed over 2-3 weeks",
      "starch per meal limit"
    ],
    "model_answer": "ม้าเป็น hindgut fermenter ถึงกระเพาะจะมีห้องเดียว แต่ caecum และ large colon เป็นส่วนใหญ่ของทางเดินอาหาร จุลินทรีย์ในส่วนนี้หมักเยื่อใย (cellulose, hemicellulose) เป็น volatile fatty acids เพื่อใช้เป็นพลังงาน อาหารหยาบยังทำให้เคี้ยวนานและสร้างน้ำลายมาก (หญ้าแห้ง 1 kg เคี้ยวราว 3500 ครั้ง เทียบกับอาหารเม็ด 800-1200 ครั้ง) ช่วยบัฟเฟอร์กรด ลดความต้องการอาหารแป้ง รักษา pH และระบบนิเวศของ hindgut ให้คงที่ ลดความเสี่ยง colic และท้องเสีย เพิ่มการเคลื่อนไหวของลำไส้ และอุ้มน้ำไว้ในทางเดินอาหาร\nแนวทางการให้อาหาร: อาหารหยาบเป็นหลักอย่างน้อย 1% ของน้ำหนักตัวต่อวัน และ 1.5-2% เหมาะกว่า ให้อาหารข้นเฉพาะเพื่อเติมส่วนที่อาหารหยาบให้ไม่พอ จำกัดแป้งไม่เกิน 2 g starch/kg BW ต่อมื้อเพื่อไม่ให้แป้งล้นไปถึง hindgut เปลี่ยนอาหารช้าๆ เพราะจุลินทรีย์ใน hindgut ใช้ 2-3 สัปดาห์ในการปรับตัว ชั่งอาหารเป็นน้ำหนักไม่ใช่ปริมาตร และมีน้ำสะอาดให้ตลอด",
    "explain": "ม้าย่อยเยื่อใยที่ลำไส้ใหญ่ ไม่ใช่ที่กระเพาะแบบสัตว์เคี้ยวเอื้อง จึงต้องได้อาหารหยาบเป็นฐานของอาหาร ม้าไม่มีความต้องการธัญพืชโดยตรง อาหารข้นเป็นแค่ตัวเสริม และแป้งที่ให้มากเกินในมื้อเดียวจะเลยไปหมักใน hindgut ทำให้ pH ลดลง",
