    "q": "อธิบายสาเหตุ + แนวทางการป้องกัน Colic laminitis",
    "keywords": [
      "high starch / grain meals",
      "starch overload in the hindgut",
      "hindgut acidosis (pH drop)",
      "abrupt feed change",
      "forage-based diet",
      "starch limits per meal",
      "gradual change over 2-3 weeks",
      "water, parasites, teeth"
    ],
    "model_answer": "สาเหตุ: อาหารแป้งสูงหรือธัญพืชปริมาณมากต่อมื้อ ทำให้แป้งล้นผ่านลำไส้เล็กไปหมักใน hindgut, pH ลดลงเป็น hindgut acidosis ระบบนิเวศของจุลินทรีย์เสีย เกิด colic และ laminitis ได้ การเปลี่ยนอาหารกะทันหัน อาหารหยาบน้อย และการกินน้ำน้อย (ม้ากินน้ำจากที่ให้น้ำอัตโนมัติน้อยกว่า) ก็เพิ่มความเสี่ยง colic ร่วมกับปัจจัยโน้มนำอื่น คือ พยาธิ ทราย ฟันไม่ดี และการใช้ NSAIDs ม้าที่มี insulin resistance หรือ PPID เสี่ยง laminitis มากขึ้นเมื่อได้แป้งสูง\nการป้องกัน: ให้อาหารหยาบเป็นหลักอย่างน้อย 1% ของน้ำหนักตัว (1.5-2% เหมาะกว่า) จำกัดแป้งต่ำกว่า 2 g starch/kg BW ต่อมื้อ เพื่อไม่ให้แป้งล้นถึง hindgut (ต่ำกว่า 1 g/kg ต่อมื้อและ 2 g/kg ต่อวันเพื่อลดความเสี่ยงแผลในกระเพาะ) และต่ำกว่า 0.3 g/kg ต่อมื้อ ในม้าที่มี insulin resistance แบ่งอาหารข้นเป็นมื้อเล็ก เปลี่ยนอาหารค่อยเป็นค่อยไปใน 2-3 สัปดาห์ มีน้ำสะอาดตลอด ถ่ายพยาธิ ดูแลฟัน และจัดการพื้นที่ปล่อยไม่ให้กินทราย",
    "explain": "ปัญหาหลักของทั้ง colic และ laminitis จากอาหารคือแป้งที่หลุดไปถึงลำไส้ใหญ่ เมื่อให้ธัญพืช pH ใน hindgut ลดลงต่ำกว่าเมื่อให้หญ้าแห้งในปริมาณเท่ากัน การป้องกันจึงเน้นให้อาหารหยาบเป็นฐาน คุมปริมาณแป้งต่อมื้อ และเปลี่ยนอาหารช้าพอให้จุลินทรีย์ปรับตัวทัน",
