    "q": "จะตรวจอะไรเพิ่มเติมหลังจากเห็นผลตรวจเหล่านี้ (bonus)\n\nข้อมูลเคส (POA respiratory): ม้าไอเรื้อรัง (chronic cough) มี bilateral nasal discharge ให้ประวัติเพิ่มว่าที่อยู่ของม้าไม่ดี อากาศไม่ถ่ายเท เดินผ่านแล้วได้กลิ่นฉี่ ต่อมาให้ผล CBC และคลิปส่องกล้องทางเดินหายใจ (endoscope)",
