    "model_answer": "NSAIDs (phenylbutazone, flunixin) เป็นยาตัวแรกของข้ออักเสบและขาเจ็บ ให้ทั่วร่างกาย corticosteroid เช่น betamethasone ฉีดเข้าข้อ (intra-articular) มักใช้ร่วมกับ hyaluronic acid (HA) และถ้าใช้เดี่ยวให้ครั้งเดียวเฉพาะที่ HA ฉีดเข้าข้อหรือเข้าเส้นเลือด PSGAG (Adequan) ฉีดเข้ากล้ามทุก 4 วันต่อเนื่อง 28 วัน และ pentosan ฉีดเข้ากล้ามทุก 7 วันต่อเนื่อง 28 วัน ใช้กับข้อเสื่อม (DJD) ส่วนยาปฏิชีวนะ (ABO) ใช้เมื่อข้อติดเชื้อ ไม่ใช่ยารักษาข้อเสื่อม",
    "explain": "ยาแต่ละกลุ่มทำหน้าที่ต่างกัน NSAIDs ลดอักเสบและปวดทั้งร่างกาย steroid ในข้อลดการอักเสบเฉพาะที่ได้แรง HA ช่วยคุณภาพน้ำไขข้อ ส่วน PSGAG และ pentosan ให้เป็นชุดต่อเนื่องเพื่อชะลอการเสื่อมของข้อ ยาปฏิชีวนะมีที่ใช้เมื่อมีการติดเชื้อเท่านั้น และไม่ใช้ NSAIDs หลายตัวร่วมกันเพราะเพิ่มความเสี่ยงแผลในทางเดินอาหารและไตเสียหาย",
